/**
 * The built-in devices' display text (docs/LOCALIZATION.md "Text from the engine").
 * `engine-text.json` lists it as the engine has it (generated by
 * `crates/ether-devices/tests/engine_text.rs`); `pnpm i18n gen` gives each string an
 * `engine.*` key (`engineText.gen.ts`) and keeps the `engine.*` block of `en.json` in step
 * (new strings get their lowercase English, gone ones are dropped). Translations are written
 * by hand like any other key.
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { I18N_DIR, readCatalog, SOURCE_LOCALE, type Catalog } from "./check.ts";
import { PROPER_NOUNS } from "./text.ts";

export const ENGINE_TEXT_LIST = join(I18N_DIR, "engine-text.json");
export const ENGINE_TEXT_FILE = join(I18N_DIR, "engineText.gen.ts");
export const ENGINE_PREFIX = "engine.";

export interface EngineEntry {
  /** As the engine sends it ("Attack Time", "Step 12"). */
  text: string;
  key: string;
  /** A numbered name ("Step 12" → `engine.step_n` with `{n}` = 12, "Operator B" → "B"). */
  n?: number | string;
  /** The English message (`en.json`'s default for a new key). */
  english: string;
}

export function readEngineText(): string[] {
  return JSON.parse(readFileSync(ENGINE_TEXT_LIST, "utf8")) as string[];
}

const slug = (s: string) =>
  s
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_|_$/g, "");

const PROPER = new Set<string>(PROPER_NOUNS);
/** Lowercase, acronyms and proper nouns aside (the lowercase rule). */
const lower = (s: string) => s.replace(/[\p{L}\p{N}]+/gu, (w) => (PROPER.has(w) ? w : w.toLowerCase()));

/** One entry per string; numbered names ("Band 3", "Step 12") share one message with `{n}`. */
export function engineEntries(list: readonly string[] = readEngineText()): EngineEntry[] {
  return list.map((text) => {
    // "Step 12", "Operator B" (not "Invert L": a side, not a number).
    const m = /^(.*\p{L}.*) (\d+|[A-H])$/u.exec(text);
    if (m) return { text, key: `${ENGINE_PREFIX}${slug(m[1]!)}_n`, n: /\d/.test(m[2]!) ? Number(m[2]) : m[2]!, english: `${lower(m[1]!)} {n}` };
    return { text, key: `${ENGINE_PREFIX}${slug(text)}`, english: lower(text) };
  });
}

/** `engineText.gen.ts`: the engine's string → its message key (and number). */
export function renderEngineTextFile(entries: readonly EngineEntry[] = engineEntries()): string {
  const lines = [
    "// Generated by `pnpm i18n gen` from engine-text.json (docs/LOCALIZATION.md): do not edit. eth-allow-case-file: the engine's English.",
    'import type { MessageKey } from "./types";',
    "",
    "/** A built-in device's display text (as the engine sends it) → its message (and `{n}`). */",
    "export const ENGINE_TEXT: Readonly<Record<string, MessageKey | readonly [MessageKey, number | string]>> = {",
    // Keys quoted only when they must be (prettier's style, so `pnpm format` leaves the file as is).
    ...entries.map(
      (e) =>
        `  ${/^[A-Za-z_$][\w$]*$/.test(e.text) ? e.text : JSON.stringify(e.text)}: ${e.n === undefined ? JSON.stringify(e.key) : `[${JSON.stringify(e.key)}, ${JSON.stringify(e.n)}]`},`,
    ),
    "};",
    "",
  ];
  return lines.join("\n");
}

/**
 * `catalog` with exactly the `engine.*` keys of `entries`: kept ones keep their text, new
 * ones get `english` (`withDefaults`: the source catalog) or are left out (a translation:
 * the missing-key check lists them), gone ones are dropped. Other keys keep their order;
 * the `engine.*` block is sorted, at the end.
 */
export function syncEngineKeys(catalog: Catalog, entries: readonly EngineEntry[], withDefaults: boolean): Catalog {
  const out: Catalog = {};
  for (const [k, v] of Object.entries(catalog)) if (!k.startsWith(ENGINE_PREFIX)) out[k] = v;
  const engine = new Map<string, string>();
  for (const e of entries) {
    const v = catalog[e.key] ?? (withDefaults ? e.english : undefined);
    if (v !== undefined && !engine.has(e.key)) engine.set(e.key, v);
  }
  for (const k of [...engine.keys()].sort()) out[k] = engine.get(k)!;
  return out;
}

/** What `pnpm i18n gen` would change (empty: up to date). */
export function engineTextErrors(): string[] {
  const entries = engineEntries();
  const errors: string[] = [];
  if (!existsSync(ENGINE_TEXT_FILE) || readFileSync(ENGINE_TEXT_FILE, "utf8") !== renderEngineTextFile(entries))
    errors.push("engineText.gen.ts is stale: run `pnpm i18n gen`");
  const en = readCatalog(SOURCE_LOCALE);
  if (JSON.stringify(syncEngineKeys(en, entries, true)) !== JSON.stringify(en))
    errors.push("en.json's engine.* keys differ from engine-text.json: run `pnpm i18n gen`");
  return errors;
}
